// src/utils/exportToExcel.js
import * as XLSX from 'xlsx';

export const exportToExcel = (data, fileName = 'ProjectDetails.xlsx') => {
    // Create a workbook
    const workbook = XLSX.utils.book_new();

    // Flatten the data structure to ensure all details are included
    const flattenedData = data.map(project => {
        return project.sections.flatMap(section => {
            return section.subsections.flatMap(subsection => {
                return subsection.documents.map(document => ({
                    ProjectName: project.name,
                    SectionName: section.name,
                    SubsectionName: subsection.name,
                    DocumentTitle: document.title,
                    DocumentDescription: document.description,
                    DocumentStatus: document.status,
                    Progress: document.progress,
                }));
            });
        });
    }).flat();

    // Create a worksheet from the flattened data
    const worksheet = XLSX.utils.json_to_sheet(flattenedData);

    // Append the worksheet to the workbook
    XLSX.utils.book_append_sheet(workbook, worksheet, 'ProjectDetails');

    // Write the workbook to a file
    XLSX.writeFile(workbook, fileName);
};
